<script setup lang="ts">
import {ref} from 'vue';
const rawOpen=ref(false),openDocs=ref<Record<string,boolean>>({});
import type {ScanInput,SDKOperation} from '../contracts';defineProps<{input?:ScanInput;operation?:SDKOperation;sourceHash?:string;sourceSnapshotId?:number;parentExecution?:{taskId:string;attempt:number}}>();
</script>
<template><details v-if="operation" class="execution-input"><summary>本次冻结的 SDK 操作输入</summary><p>源码快照 #{{sourceSnapshotId??'未知'}} · 内容 SHA-256 <code>{{sourceHash??'未知'}}</code></p><p>{{operation.kind==='validate'?'复核覆盖完整源码快照，SDK 费用未知；来源漏洞的原始证据在创建操作时冻结。':'预检使用本次冻结的模型、扫描范围和知识文档配置。'}}</p><pre>{{JSON.stringify(operation,null,2)}}</pre></details><details v-if="input" class="execution-input"><summary>本次冻结的扫描输入与知识文档</summary><dl><template v-if="parentExecution"><dt>父 Web 扫描</dt><dd><RouterLink :to="'/scans/'+parentExecution.taskId">#{{parentExecution.taskId}} · 第 {{parentExecution.attempt}} 次执行</RouterLink></dd></template><template v-for="key in (['subagents','workflowId','safetyIdentifier','parentScanId','expectedPluginVersion','failureSeverity'] as const)" :key="key"><template v-if="input[key]!==undefined"><dt>{{({subagents:'子代理数量',workflowId:'SDK 工作流 ID',safetyIdentifier:'隐私标识',parentScanId:'父 SDK Scan ID',expectedPluginVersion:'预期插件版本',failureSeverity:'SDK 严重程度阈值'})[key]}}</dt><dd>{{input[key]}}</dd></template></template></dl><p v-if="!input.knowledge.length">本次未引用知识文档。</p><section v-for="d in input.knowledge" :key="d.versionId"><h3><RouterLink :to="'/knowledge?version='+d.versionId">{{d.title}} · 版本记录 #{{d.versionId}}</RouterLink></h3><p>SHA-256 · <code>{{d.sha256}}</code></p><details @toggle="openDocs[d.versionId]=($event.currentTarget as HTMLDetailsElement).open"><summary>查看引用时的原始正文</summary><pre v-if="openDocs[d.versionId]">{{d.content}}</pre></details></section><section v-for="key in (['scanPrompt','validationPrompt','postScanPrompt'] as const)" :key="key"><template v-if="input[key]"><h3>{{({scanPrompt:'补充扫描指令',validationPrompt:'自定义验证指令',postScanPrompt:'扫描后处理指令'})[key]}}</h3><pre>{{input[key]}}</pre></template></section><details @toggle="rawOpen=($event.currentTarget as HTMLDetailsElement).open"><summary>原始输入合同</summary><pre v-if="rawOpen">{{JSON.stringify(input,null,2)}}</pre></details></details></template>
